import {renderView,section,button,form,field,textInput} from '../ui/view.js';import {SettingsService} from './literary-services-settings-service.js';import {AuthService} from './literary-services-auth-service.js';import {store} from '../core/state-store.js';import {el,formDataObject} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';import {events} from '../core/event-bus.js';
export async function settingsView(){const settings=store.get('settings')||await SettingsService.get(),body=document.createDocumentFragment();const a=settings.accessibility||{};body.append(section('Accessibility',[form('',[
 field('Text scale',el('input',{name:'fontScale',type:'number',min:.75,max:2,step:.05,value:a.fontScale||1})),field('High contrast',el('input',{name:'highContrast',type:'checkbox',checked:Boolean(a.highContrast)})),field('Reduce motion',el('input',{name:'reduceMotion',type:'checkbox',checked:Boolean(a.reduceMotion)})),field('Dyslexia-friendly mode hook',el('input',{name:'dyslexiaFriendly',type:'checkbox',checked:Boolean(a.dyslexiaFriendly)})),field('Large targets',el('input',{name:'largeTargets',type:'checkbox',checked:a.largeTargets!==false}))
],async(fd,f)=>{const d=formDataObject(f),next={...settings,accessibility:{...a,fontScale:Number(d.fontScale)||1,highContrast:fd.has('highContrast'),reduceMotion:fd.has('reduceMotion'),dyslexiaFriendly:fd.has('dyslexiaFriendly'),largeTargets:fd.has('largeTargets')}};await SettingsService.update(next);notify('Accessibility settings saved.');},{submitLabel:'Save accessibility'})]));
 body.append(section('Security & recovery',[button('Manage active sessions',async()=>{const r=await AuthService.sessions();const pre=el('pre',{text:JSON.stringify(r.sessions||[],null,2)});document.querySelector('#route-view').append(pre);}),button('Generate recovery codes',async()=>{const r=await AuthService.generateRecoveryCodes();const pre=el('pre',{text:(r.codes||[]).join('\n')});pre.setAttribute('aria-label','New one-time recovery codes');document.querySelector('#route-view').append(pre);notify('Save these recovery codes now; the backend stores only hashes.');}),button('Enable optional two-factor verification',async()=>{const method=window.prompt('Verification method (email or phone):','email')||'email';const destination=window.prompt(`Verification ${method}:`)||'';if(destination){await AuthService.enableTwoFactor({method,destination});notify('Two-factor settings updated.');}}),button('Connect personal Google Drive',async()=>{const r=await AuthService.driveLinkStart({});if(r.url)window.open(r.url,'_blank','noopener');else notify(r.message||'Drive linking started.');})]));
 body.append(section('Account',[button('Sign out',async()=>{await AuthService.logout();events.emit('auth:signed-out',{});})]));renderView('Settings',{description:'Profile, theme hooks, accessibility, Drive storage, optional 2FA, recovery contacts, devices, and backup controls.',body});}
